  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I'],
];

/**
 * Convert an integer in the range 1..3999 to a Roman numeral.
 * @param {number} n
 * @returns {string}
 * @throws {TypeError} if n is not a number
 * @throws {RangeError} if n is not an integer in 1..3999
 */
export function toRoman(n) {
  if (typeof n !== 'number') {
    throw new TypeError(`Expected a number, got ${typeof n}`);
  }
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError(`Expected an integer between 1 and 3999, got ${n}`);
  }

  let result = '';
  let rest = n;
  for (const [value, symbol] of NUMERALS) {
    while (rest >= value) {
      result += symbol;
      rest -= value;
    }
  }
  return result;
}
"}

{"path": "test/roman.test.js", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toRoman } from '../src/roman.js';

test('converts basic symbols', () => {
  assert.equal(toRoman(1), 'I');
  assert.equal(toRoman(5), 'V');
  assert.equal(toRoman(10), 'X');
  assert.equal(toRoman(50), 'L');
  assert.equal(toRoman(100), 'C');
  assert.equal(toRoman(500), 'D');
  assert.equal(toRoman(1000), 'M');
});

test('uses subtractive notation', () => {
  assert.equal(toRoman(4), 'IV');
  assert.equal(toRoman(9), 'IX');
  assert.equal(toRoman(40), 'XL');
  assert.equal(toRoman(90), 'XC');
  assert.equal(toRoman(400), 'CD');
  assert.equal(toRoman(900), 'CM');
});

test('converts composite numbers', () => {
  assert.equal(toRoman(3), 'III');
  assert.equal(toRoman(14), 'XIV');
  assert.equal(toRoman(58), 'LVIII');
  assert.equal(toRoman(1994), 'MCMXCIV');
  assert.equal(toRoman(2024), 'MMXXIV');
  assert.equal(toRoman(3999), 'MMMCMXCIX');
});

test('throws RangeError outside 1..3999', () => {
  for (const n of [0, -1, 4000, 10000, Infinity, -Infinity]) {
    assert.throws(() => toRoman(n), RangeError, `n = ${n}`);
  }
});

test('throws RangeError for non-integers and NaN', () => {
  for (const n of [1.5, 3998.9, NaN]) {
    assert.throws(() => toRoman(n), RangeError, `n = ${n}`);
  }
});

test('throws TypeError for non-numbers', () => {
  for (const n of ['10', null, undefined, 10n, {}]) {
    assert.throws(() => toRoman(n), TypeError);
  }
});

test('produces unique, non-empty numerals for the full range', () => {
  const seen = new Set();
  for (let n = 1; n <= 3999; n++) {
    const r = toRoman(n);
    assert.match(r, /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/);
    seen.add(r);
  }
  assert.equal(seen.size, 3999);
});
"}
